insert into public.packs (id, version, sector, description, config) values
  ('farm-pen', '0.1.0', null, 'A pen or corral the owner draws. A wild animal inside, or a farm animal outside, raises an in-app alert only after it stays that way for sustain_s seconds (default 3). No SMS. No real field clip yet: alerts are NOT VERIFIED.', '{"id": "farm-pen", "version": "0.1.0", "locale": "en", "jurisdiction": "global", "description": "A pen or corral the owner draws. A wild animal inside, or a farm animal outside, raises an in-app alert only after it stays that way for sustain_s seconds (default 3). No SMS. No real field clip yet: alerts are NOT VERIFIED.", "targets": [{"prompt": "cow", "class": "cow"}, {"prompt": "goat", "class": "goat"}, {"prompt": "coyote", "class": "coyote", "fallbacks": ["fox", "dog"]}], "sampling": {"fps": 1, "mode": "video_track"}, "geometry": {"zones": [{"id": "pen", "polygon": [[0.2, 0.2], [0.8, 0.2], [0.8, 0.8], [0.2, 0.8]]}], "lines": []}, "metrics": ["unique_count", "zone_alerts"], "alerts": [{"id": "wild_enters", "kind": "wild_enters_zone", "severity": "emergency", "sustain_s": 3, "message": "Wild animal entered the pen and stayed {sustain_s} s"}, {"id": "farm_leaves", "kind": "farm_leaves_zone", "severity": "high", "sustain_s": 3, "message": "Farm animal left the pen and stayed out {sustain_s} s"}], "privacy": {"blur": ["person"], "identity": false, "store": "alerts_and_boxes"}, "station_defaults": {"station": "north-pen", "local_tz_offset_hours": -6}, "output": {"annotated_video": false}}'::jsonb),
  ('fauna-camtrap', '0.4.0', 'fauna', 'Camera-trap pack (LILA CDLA). Primary prompt ''coyote'' with fallbacks [''animal'',''fox'',''dog''] if SAM finds nothing. A person is blurred from the SAM box (no face ID). Re-entry dedup is configurable.', '{"id": "fauna-camtrap", "version": "0.4.0", "locale": "es-CR", "jurisdiction": "global", "description": "Camera-trap pack (LILA CDLA). Primary prompt ''coyote'' with fallbacks [''animal'',''fox'',''dog''] if SAM finds nothing. A person is blurred from the SAM box (no face ID). Re-entry dedup is configurable.", "targets": [{"prompt": "coyote", "class": "coyote", "fallbacks": ["animal", "fox", "dog"]}, {"prompt": "person", "class": "person"}], "sampling": {"fps": 5, "mode": "video_track", "chunk_s": 60, "overlap_s": 2}, "geometry": {"zones": [{"id": "frame_completo", "polygon": [[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]]}], "lines": []}, "metrics": ["unique_count", "dwell"], "dedup": {"iou_stitch": 0.3, "reentry_window_s": 20, "reentry_edge_px": 80, "center_dist_factor": 2.0, "edge_dist_factor": 4.0}, "alerts": [{"id": "person_at_night", "when": "class == ''person'' AND local_hour NOT IN 6..18", "severity": "high", "message": "Person detected at night at {station}"}, {"id": "target_species", "when": "class == ''coyote'' AND unique_count >= 1", "severity": "info", "message": "Coyote recorded: {unique_count} individuals"}], "voice": {"languages": ["es", "en"], "link_by": ["timestamp", "station"]}, "report": {"template": "fauna_estacion_v1", "sections": ["resumen", "especies", "eventos", "notas_campo", "alertas"]}, "privacy": {"blur": ["person"], "store": "aggregates_and_blurred_clips", "identity": false, "blur_radius": 28}, "station_defaults": {"station": "demo-seattleish", "local_tz_offset_hours": -8}, "output": {"annotated_video": true, "blurred_video": true}}'::jsonb),
  ('multitudes-densidad', '0.1.0', 'multitudes', 'People per zone on sampled frames (SAM image mode, no 16-object cap). Does not follow individuals or recognize faces: how many, not who.', '{"id": "multitudes-densidad", "version": "0.1.0", "locale": "es-CR", "jurisdiction": "global", "description": "People per zone on sampled frames (SAM image mode, no 16-object cap). Does not follow individuals or recognize faces: how many, not who.", "targets": [{"prompt": "person", "class": "person"}], "sampling": {"fps": 1, "mode": "image_sample"}, "geometry": {"zones": [{"id": "zone_1", "polygon": [[0.1, 0.4], [0.9, 0.4], [0.9, 0.95], [0.1, 0.95]], "area_m2": 25}], "lines": []}, "metrics": ["persons_per_zone", "density_per_m2", "peak_density"], "density": {"point": "bbox_bottom_center", "smoothing_window_s": 5, "sustain_s": 10}, "alerts": [{"id": "density_high", "when": "density_per_m2 >= 6 SUSTAINED sustain_s", "severity": "high", "message": "Crush risk: {density_per_m2} people/m² in {zone} for {sustain_s} s. Open an exit or slow entry."}], "voice": {"languages": ["es", "en"], "link_by": ["timestamp", "station"]}, "report": {"template": "multitudes_evento_v1", "sections": ["resumen", "pico_por_zona", "alertas", "notas_campo", "limites"]}, "privacy": {"blur": ["person"], "blur_target": "full_bbox", "store": "aggregates_only", "identity": false, "tracking": false, "blur_radius": 28}, "station_defaults": {"station": "demo-multitudes", "local_tz_offset_hours": -6}, "output": {"annotated_video": true, "blurred_video": true, "heatmap": true}}'::jsonb),
  ('protected-zone', '0.1.0', null, 'A person who stays inside a protected zone raises an in-app alert for a human to review. Faces are blurred. No name, no face id, no notice to authorities. NOT VERIFIED until a labeled field clip exists.', '{"id": "protected-zone", "version": "0.1.0", "locale": "en", "jurisdiction": "global", "description": "A person who stays inside a protected zone raises an in-app alert for a human to review. Faces are blurred. No name, no face id, no notice to authorities. NOT VERIFIED until a labeled field clip exists.", "targets": [{"prompt": "person", "class": "person"}], "sampling": {"fps": 1, "mode": "video_track"}, "geometry": {"zones": [{"id": "ridge", "polygon": [[0.25, 0.25], [0.75, 0.25], [0.75, 0.75], [0.25, 0.75]]}], "lines": []}, "metrics": ["zone_alerts"], "alerts": [{"id": "person_in_zone", "kind": "person_in_zone", "severity": "high", "sustain_s": 3, "message": "Person detected in protected zone at {local_time}"}], "privacy": {"blur": ["person", "face"], "blur_target": "full_bbox", "identity": false, "store": "blurred_boxes_only", "notify_authorities": false}, "station_defaults": {"station": "ridge-gate", "local_hhmm": "06:41"}, "output": {"annotated_video": false}}'::jsonb),
  ('transito-giros', '0.1.0', 'transito', 'Turn matrix N/S/E/W at an intersection. SAM on each approach crop (16 objects per frame cap). budget_usd 0.50. Framing calibrated for data/transit/wicker_park_intersection (overhead view). Counts are NOT VERIFIED until QA.', '{"id": "transito-giros", "version": "0.1.0", "locale": "es-CR", "jurisdiction": "global", "description": "Turn matrix N/S/E/W at an intersection. SAM on each approach crop (16 objects per frame cap). budget_usd 0.50. Framing calibrated for data/transit/wicker_park_intersection (overhead view). Counts are NOT VERIFIED until QA.", "targets": [{"prompt": "car", "class": "car", "fallbacks": ["vehicle", "automobile"]}, {"prompt": "motorcycle", "class": "motorcycle", "fallbacks": ["motorbike", "scooter"]}, {"prompt": "bus", "class": "bus"}, {"prompt": "truck", "class": "truck", "fallbacks": ["van", "pickup"]}, {"prompt": "bicycle", "class": "bicycle", "fallbacks": ["bike", "cyclist"]}, {"prompt": "person", "class": "person", "fallbacks": ["pedestrian", "people"]}], "sampling": {"fps": 5, "mode": "video_track", "chunk_s": 60, "overlap_s": 2}, "budget_usd": 0.5, "access_crops": true, "geometry": {"approaches": [{"id": "acceso_N", "line": [[0.3, 0.34], [0.7, 0.34]], "roi": [0.28, 0.0, 0.72, 0.36]}, {"id": "acceso_S", "line": [[0.3, 0.66], [0.7, 0.66]], "roi": [0.28, 0.64, 0.72, 1.0]}, {"id": "acceso_E", "line": [[0.66, 0.3], [0.66, 0.7]], "roi": [0.64, 0.28, 1.0, 0.72]}, {"id": "acceso_O", "line": [[0.34, 0.3], [0.34, 0.7]], "roi": [0.0, 0.28, 0.36, 0.72]}], "lines": [], "zones": []}, "metrics": ["turning_movements", "unique_count", "dwell"], "turning_rules": {"_": "por_orientacion"}, "dedup": {"iou_stitch": 0.3, "reentry_window_s": 15, "reentry_edge_px": 80, "center_dist_factor": 2.0, "edge_dist_factor": 4.0}, "alerts": [{"id": "flujo_alto_autos", "when": "class == ''car'' AND unique_count >= 20", "severity": "medium", "message": "Heavy car flow at {station}: {unique_count} unique"}, {"id": "presencia_peatones", "when": "class == ''person'' AND unique_count >= 5", "severity": "info", "message": "Person detected in the intersection"}, {"id": "motos_presentes", "when": "class == ''motorcycle'' AND unique_count >= 3", "severity": "info", "message": "Motorcycles detected at {station}: {unique_count}"}], "voice": {"languages": ["es", "en"], "link_by": ["timestamp", "station"]}, "report": {"template": "transito_interseccion_v1", "sections": ["resumen", "matriz_giros", "por_clase", "alertas", "limites"]}, "privacy": {"blur": ["person"], "blur_target": "full_bbox", "store": "aggregates_and_blurred_clips", "identity": false, "blur_radius": 28}, "station_defaults": {"station": "wicker-park", "local_tz_offset_hours": -5}, "output": {"annotated_video": true, "blurred_video": true}}'::jsonb)
